const items = [];

for (const item of $input.all()) {
  const binary = item.binary;

  // Asumiendo que el archivo descargado se llama 'data' en el objeto binary:
  if (binary && binary.data) {
    const file = binary.data;
    const base64Content = file.data; // El dato binario ya suele estar en base64 en n8n

    // Crear un nuevo item con la metadata necesaria para el prompt
    items.push({
      json: {
        fileName: file.fileName,
        fileType: file.mimeType,
        base64Data: base64Content,
        urlDefault: "https://default.url/del/documento" // La URL por defecto
      }
    });
  } else {
    // Manejo de error si no se encuentra el archivo binario
    items.push({ json: { error: 'No se encontró el archivo binario esperado.' } });
  }
}

return items;

const rawText = $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('No se recibió respuesta de Gemini');
}

let dataObject;
try {
  dataObject = JSON.parse(rawText);
} catch (error) {
  const cleanText = rawText.replace(/```json|```/g, '').trim();
  try {
    dataObject = JSON.parse(cleanText);
  } catch (e) {
    throw new Error('La respuesta de Gemini no es un JSON válido: ' + e.message);
  }
}

const pages = dataObject.document_pages || [];

if (pages.length === 0) {
  throw new Error('No se encontraron páginas en la respuesta');
}

// Obtener metadata del input
const inputData = $input.first().json;
const fileId = inputData.fileId;


return pages.map((pageItem) => ({
  json: {
    page: pageItem.page,
    section: pageItem.section || 'General',
    description: pageItem.description || '',
    text: pageItem.text || '',
    tables: pageItem.tables || [],
    images_desc: pageItem.images_desc || [],
    fileName: pageItem.fileName || 'desconocido',
    fileId: fileId,
    url: pageItem.url || ''
  }
}));

