// Input: fileName desde Google Drive
// Input: lista de archivos Bitrix desde el HTTP Request
// Este code encuentra el archivo correspondiente, arma la URL y el campo "Ubicacion"

const googleFile = $json.originalFilename || $('Code').first().json.fileName;
if (!googleFile) {
  throw new Error("No se encontró el nombre del archivo para hacer el match.");
}

const bitrixList = $('Britrix File').first().json.result;
if (!bitrixList || !Array.isArray(bitrixList)) {
  throw new Error("No llegó la lista de archivos Bitrix.");
}

// 1. Buscar el archivo en Bitrix que coincide EXACTO con el nombre
const match = bitrixList.find(f => f.NAME.trim() === googleFile.trim());

if (!match) {
  return [{
    json: {
      error: "No se encontró match en Bitrix",
      googleFile
    }
  }];
}

// 2. Construir la URL de visualización
const objectId = match.ID;
const visualUrl = `https://mobilvendor.bitrix24.es/bitrix/tools/disk/focus.php?objectId=${objectId}&cmd=show&action=showObjectInGrid&ncc=1`;

// 3. Obtener la Ubicacion desde el DETAIL_URL
//    Ejemplo DETAIL_URL:
//    https://mobilvendor.bitrix24.es/docs/file/ISO27001_2022/Seguridad de la Información/Requisitos/4 Contexto de la Organización.pdf

const detail = match.DETAIL_URL || "";
let ubicacion = "";

if (detail.includes("ISO27001_2022/")) {
  const part = detail.split("ISO27001_2022/")[1];

  // quitar el nombre del archivo al final
  ubicacion = part.replace(googleFile, "").replace(/\/$/, "");
}

// Devolver merge para que lo uses en Pinecone
return [{
  json: {
    bitrixId: match.ID,
    bitrixFileName: match.NAME,
    bitrixDetail: match.DETAIL_URL,
    bitrixViewUrl: visualUrl,
    ubicacion
  }
}];

const pages = $('Split by Page').all().map(i => i.json);
const bitrix = $('Match Bitrix File + Build Metadata').first().json || {};

const items = [];

for (const pageData of pages) {

  let fullPageContent = '';

  // 🔹 Texto
  if (pageData.text) {
    fullPageContent += pageData.text + '\n\n';
  }

  // 🔹 Tablas
  if (pageData.tables && pageData.tables.length > 0) {
    fullPageContent += '=== TABLAS ===\n';
    pageData.tables.forEach((table, idx) => {
      fullPageContent += `\n--- Tabla ${idx + 1}: ${table.table_title || 'Sin título'} ---\n`;
      fullPageContent += table.content_json + '\n';
    });
    fullPageContent += '\n';
  }

  // 🔹 Imágenes
  if (pageData.images_desc && pageData.images_desc.length > 0) {
    fullPageContent += '=== IMÁGENES ===\n';
    pageData.images_desc.forEach((imgDesc, idx) => {
      fullPageContent += `Imagen ${idx + 1}: ${imgDesc}\n`;
    });
  }

  // 🔥 ARMAR EL JSON FINAL QUE VA A PINECONE
  items.push({
    json: {
      pageContent: fullPageContent.trim(),
      metadata: {
        // 🔥 Metadata real del documento
        document: pageData.fileName,
        fileId: pageData.fileId,
        source_url: bitrix.bitrixViewUrl || pageData.url,

        // 🔥 Metadata de Bitrix
        bitrixId: bitrix.bitrixId || '',
        ubicacion: bitrix.ubicacion || '',
        bitrixDetailUrl: bitrix.bitrixDetail || '',

        // 🔥 Metadata por página
        page: pageData.page,
        section: pageData.section,
        description: pageData.description,
        textLength: fullPageContent.length,
        hasTable: (pageData.tables?.length || 0) > 0,
        tableCount: pageData.tables?.length || 0,
        hasImages: (pageData.images_desc?.length || 0) > 0,
        imageCount: pageData.images_desc?.length || 0,

        // 🔥 ISO
        compliance: 'ISO27001:2022',
        processedAt: new Date().toISOString()
      }
    }
  });
}

return items;

const output = [];

for (const item of $input.all()) {
  const text = item.json.candidates[0].content.parts[0].text;

  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    continue;
  }

  if (!data.document_pages) continue;

  for (const page of data.document_pages) {
    output.push({
      json: {
        fileName: page.fileName || item.json.fileName,
        bitrixId: page.bitrixId,
        bitrixDetailUrl: page.bitrixDetailUrl,
        text: page.text,
        page: page.page,
        description: page.description,
        tables: page.tables,
        images: page.images_desc,
        source_url: page.source_url,
        ubicacion: page.ubicacion
      }
    });
  }
}

return output;

