// ===============================================
// PREPARE DOCUMENTS FOR PINECONE
// Combina contenido de páginas con metadata de Bitrix
// ===============================================

const pages = $input.all().map(i => i.json);

if (!pages || pages.length === 0) {
  throw new Error('No se recibieron páginas para procesar');
}

const items = [];

for (const pageData of pages) {

  // ===============================================
  // 1. CONSTRUIR CONTENIDO COMPLETO DE LA PÁGINA
  // ===============================================
  let fullPageContent = '';

  // 🔹 Texto principal
  if (pageData.text) {
    fullPageContent += pageData.text + '\n\n';
  }

  // 🔹 Tablas (si existen)
  if (pageData.tables && pageData.tables.length > 0) {
    fullPageContent += '=== TABLAS ===\n';
    pageData.tables.forEach((table, idx) => {
      fullPageContent += `\n--- Tabla ${idx + 1}: ${table.table_title || 'Sin título'} ---\n`;
      fullPageContent += table.content_json + '\n';
    });
    fullPageContent += '\n';
  }

  // 🔹 Descripciones de imágenes (si existen)
  if (pageData.images_desc && pageData.images_desc.length > 0) {
    fullPageContent += '=== IMÁGENES ===\n';
    pageData.images_desc.forEach((imgDesc, idx) => {
      fullPageContent += `Imagen ${idx + 1}: ${imgDesc}\n`;
    });
  }

  // ===============================================
  // 2. VALIDAR QUE TENEMOS METADATA DE BITRIX
  // ===============================================
  if (!pageData.bitrixId || !pageData.ubicacion) {
    console.warn(`⚠️ Página ${pageData.page} sin metadata de Bitrix completa`);
  }

  // ===============================================
  // 3. ARMAR DOCUMENTO PARA PINECONE
  // ===============================================
  items.push({
    json: {
      pageContent: fullPageContent.trim(),
      metadata: {
        // 📄 Metadata del documento
        document: pageData.fileName || 'documento_sin_nombre.pdf',
        source_url: pageData.source_url || '',

        // 📁 Metadata de Bitrix (ubicación en carpetas)
        bitrixId: pageData.bitrixId || '',
        ubicacion: pageData.ubicacion || '',
        bitrixDetailUrl: pageData.bitrixDetailUrl || '',

        // 📖 Metadata específica de la página
        page: pageData.page || 0,
        section: pageData.section || 'General',
        description: pageData.description || '',

        // 📊 Metadata de contenido
        textLength: fullPageContent.length,
        hasTable: (pageData.tables?.length || 0) > 0,
        tableCount: pageData.tables?.length || 0,
        hasImages: (pageData.images_desc?.length || 0) > 0,
        imageCount: pageData.images_desc?.length || 0,

        // 🔐 Metadata de compliance
        compliance: 'ISO27001:2022',
        processedAt: new Date().toISOString()
      }
    }
  });
}

// ===============================================
// 🔥 SIEMPRE RETORNAR ARRAY DE ITEMS
// ===============================================
return items;

// ===============================================
//  CONFIG
// ===============================================
const BITRIX_URL = "https://mobilvendor.bitrix24.es/rest/1/ghq4a7p2r32rd5u9/";
const ROOT_FOLDER = "39991";

// ===============================================
//  Obtener hijos de carpeta Bitrix
// ===============================================
async function getChildren(folderId, ctx) {
  const response = await ctx.helpers.httpRequest({
    method: "POST",
    url: `${BITRIX_URL}disk.folder.getchildren.json`,
    body: { id: folderId },
    json: true
  });
  return response.result || [];
}

// ===============================================
//  Recorrido recursivo
// ===============================================
async function scanFolder(folderId, currentPath, ctx) {
  let results = [];
  const children = await getChildren(folderId, ctx);

  for (const item of children) {
    // ---------- SUBCARPETA ----------
    if (item.TYPE === "folder") {
      // ✅ CORREGIDO: Agregar '/' solo si currentPath no está vacío
      const separator = currentPath ? "/" : "";
      const newPath = currentPath + separator + item.NAME;
      const sub = await scanFolder(item.ID, newPath, ctx);
      results.push(...sub);
    }

    // ---------- ARCHIVO ----------
    if (item.TYPE === "file") {
      const name = item.NAME || "";
      const ext = name.includes(".")
        ? name.split(".").pop().toLowerCase()
        : "";

      results.push({
        fileName: name,
        tipo: ext,
        extension: ext,
        ubicacion: currentPath, // ✅ Sin '/' al final
        bitrixId: item.ID,
        bitrixDetailUrl: item.DETAIL_URL,
        bitrixDownload: item.DOWNLOAD_URL,
        bitrixViewUrl: `https://mobilvendor.bitrix24.es/bitrix/tools/disk/focus.php?objectId=${item.ID}&cmd=show&action=showObjectInGrid&ncc=1`
      });
    }
  }
  return results;
}


// ===============================================
//  EJECUCIÓN
// ===============================================
const output = await scanFolder(ROOT_FOLDER, "", this);

return output.map(e => ({ json: e }));

// Convierte el binario real a Base64 (no el placeholder "filesystem-v2")
const out = [];

for (let i = 0; i < items.length; i++) {
  const binProp = 'data'; // <- tu propiedad binaria se llama "data" (según la captura)

  if (!items[i].binary?.[binProp]) {
    out.push({
      json: {
        error: 'No llegó binario en items[i].binary.data',
        debugKeys: Object.keys(items[i].binary || {}),
      },
    });
    continue;
  }

  // ✅ Esta API lee el binario REAL aunque n8n lo guarde como filesystem-v2
  const buf = await this.helpers.getBinaryDataBuffer(i, binProp);
  const base64 = buf.toString('base64');

  out.push({
    json: {
      fileName: items[i].binary[binProp].fileName,
      fileType: items[i].binary[binProp].mimeType || 'application/pdf',
      base64Data: base64,

      // tus campos extra (si existen)
      bitrixId: items[i].json.bitrixId,
      bitrixDetailUrl: items[i].json.bitrixDetailUrl,
      source_url: items[i].json.source_url,
      ubicacion: items[i].json.ubicacion,
    },
  });
}

return out;

// ===============================================
// EXCLUIR ARCHIVOS POR bitrixId (lista negra)
// ===============================================

// 1) Lista negra (IDs a excluir)
const EXCLUDE_IDS = new Set([
  39993, 39995, 39997, 39999, 40001, 40003, 40005, 40007, 40009, 40011,
  40013, 40015, 40017, 40019, 40021, 40023, 40025, 40027, 40029, 40031
]);

// 2) Filtrar items
const kept = [];
const removed = [];

for (const item of items) {
  const id = Number(item.json.bitrixId);

  if (EXCLUDE_IDS.has(id)) {
    removed.push(item.json);
    continue;
  }

  kept.push(item);
}

// 3) (Opcional) Debug: deja 1 item con resumen en el log
console.log(`✅ Pasan: ${kept.length}`);
console.log(`⛔ Excluidos: ${removed.length}`);
if (removed.length) console.log("Ejemplos excluidos:", removed.slice(0, 5));

// 4) Devolver sólo los que pasan
return kept;
